/**
 * Loads the measured engine builtin sets from `data/engine-probe.json`.
 *
 * The data file is generated by `scripts/probe-engines.ts` against real
 * browsers. It is checked in so the analyzer works offline and so that any
 * change to the browser behaviour is visible as a diff.
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import type { Engine, EngineBuiltins } from './engine-semantics.ts';
import { ENGINES } from './engine-semantics.ts';

interface ProbeFile {
  provenance: { measuredAt: string; method: string };
  engines: Record<
    Engine,
    {
      userAgent: string;
      windowChain: string[];
      documentChain: string[];
      documentOwn: string[];
    }
  >;
}

const here = dirname(fileURLToPath(import.meta.url));
const DATA_PATH = join(here, '..', '..', 'data', 'engine-probe.json');

let cache: Record<Engine, EngineBuiltins> | null = null;

/** Load and memoize the measured builtin sets for all engines. */
export function loadEngineBuiltins(): Record<Engine, EngineBuiltins> {
  if (cache) return cache;
  const raw = JSON.parse(readFileSync(DATA_PATH, 'utf8')) as ProbeFile;
  const result = {} as Record<Engine, EngineBuiltins>;
  for (const engine of ENGINES) {
    const e = raw.engines[engine];
    if (!e) throw new Error(`engine-probe.json is missing engine "${engine}"`);
    result[engine] = {
      engine,
      windowChain: new Set(e.windowChain),
      documentChain: new Set(e.documentChain),
      documentOwn: new Set(e.documentOwn),
    };
  }
  cache = result;
  return result;
}

/** Expose the provenance block for reports. */
export function probeProvenance(): ProbeFile['provenance'] {
  const raw = JSON.parse(readFileSync(DATA_PATH, 'utf8')) as ProbeFile;
  return raw.provenance;
}
